INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt der Arbeitsschutz nur für gefährliche Berufe?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Arbeitsplätze relevant"}, {"text": "Ja", "correct": false, "because": "Allgemeiner Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Arbeitsschutz?', 3, '[{"text": "Gesundheit der Arbeitnehmer sichern", "correct": true, "because": "Primäres Ziel"}, {"text": "Produktivität steigern", "correct": false, "because": "Indirekter Effekt"}, {"text": "Kosten senken", "correct": false, "because": "Nicht Hauptzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Arbeitsschutz?', 5, '[{"text": "Schutzausrüstung", "correct": true, "because": "Schützt physisch"}, {"text": "Arbeitszeitregelung", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Marketingstrategien", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsschutz ist gesetzlich vorgeschrieben. b) Er gilt nur für Vollzeitkräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Beschäftigten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Arbeitsschutz?', 4, '[{"text": "Sicherheitsvorschriften", "correct": false, "because": "Grundlage"}, {"text": "Gefährdungsbeurteilung", "correct": false, "because": "Pflicht"}, {"text": "Bürogestaltung", "correct": true, "because": "Ästhetik irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Arbeitsschutz Schulungen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Nein", "correct": false, "because": "Teil des Schutzes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zum Arbeitsschutz?', 3, '[{"text": "Ergonomische Arbeitsplätze", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Werbekampagnen", "correct": false, "because": "Kein Schutz"}, {"text": "Preisverhandlungen", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung des Arbeitsschutzes?', 5, '[{"text": "Gefährdungsbeurteilung", "correct": true, "because": "Identifiziert Risiken"}, {"text": "Sicherheitsunterweisung", "correct": true, "because": "Schult Mitarbeiter"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitsschutz reduziert Unfälle. b) Er ist optional für Arbeitgeber. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht, nicht optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Arbeitsschutz unwichtig?', 4, '[{"text": "Arbeitssicherheit", "correct": false, "because": "Kernbereich"}, {"text": "Gesundheitsschutz", "correct": false, "because": "Hauptziel"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Arbeitsschutz gesetzlich geregelt?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitsschutzgesetz"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt der Arbeitsschutz?', 4, '[{"text": "Weniger Arbeitsunfälle", "correct": true, "because": "Sicherheit erhöht"}, {"text": "Gesundere Mitarbeiter", "correct": true, "because": "Schutzmaßnahmen"}, {"text": "Höhere Gewinne", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitsschutz nur für große Firmen gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Betriebe"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Arbeitsschutz?', 3, '[{"text": "Mitarbeitersicherheit", "correct": true, "because": "Hauptfokus"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsschutz schützt vor Gefahren. b) Er ist nur für Büroarbeiten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt überall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat mangelhafter Arbeitsschutz?', 5, '[{"text": "Höhere Unfallzahlen", "correct": true, "because": "Risiken steigen"}, {"text": "Rechtliche Konsequenzen", "correct": true, "because": "Verstöße strafbar"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Arbeitsschutz unwichtig?', 3, '[{"text": "Schutzausrüstung", "correct": false, "because": "Schützt direkt"}, {"text": "Unterweisungen", "correct": false, "because": "Sensibilisiert"}, {"text": "Bürodesign", "correct": true, "because": "Ästhetik"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Umfasst Arbeitsschutz psychische Gesundheit?', 3, '[{"text": "Ja", "correct": true, "because": "Auch Stressschutz"}, {"text": "Nein", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitsschutz regelmäßige Kontrollen erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherstellung"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme wähle ich für den Arbeitsschutz?', 4, '[{"text": "Sicherheitsbeauftragter", "correct": true, "because": "Überwacht Maßnahmen"}, {"text": "Marketingkampagne", "correct": false, "because": "Kein Schutz"}, {"text": "Kostenoptimierung", "correct": false, "because": "Anderer Fokus"}]');
